import Phaser from 'phaser';
import ModeSelectScene from './scenes/ModeSelectScene';
import DifficultySelectScene from './scenes/DifficultySelectScene';
import GameScene from './scenes/GameScene';
import LeaderboardScene from './scenes/LeaderboardScene';
import ReleaseNotesScene from './scenes/ReleaseNotesScene';
import CharacterSelectScene from './scenes/CharacterSelectScene';
import GachaScene from './scenes/GachaScene';
import { ensureLoggedIn } from './utils/auth';
import './style.css';

const config: Phaser.Types.Core.GameConfig = {
  type: Phaser.AUTO,
  width: 400,
  height: 600,
  parent: 'game-container',
  backgroundColor: '#87CEEB',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0, x: 0 },
      debug: false, // 히트박스 on/off
      fixedStep: false
    }
  },
  scene: [ModeSelectScene, DifficultySelectScene, GameScene, LeaderboardScene, ReleaseNotesScene, CharacterSelectScene, GachaScene],
  scale: {
    mode: Phaser.Scale.FIT,
    autoCenter: Phaser.Scale.CENTER_BOTH
  },
  render: {
    antialias: true,
    roundPixels: true
  },
  fps: {
    target: 60,
    smoothStep: true
  }
};

// 로그인은 백그라운드에서 진행 (Phaser 게임 생성을 지연시키지 않음)
// ensureLoggedIn()을 await하면 캔버스가 비동기 컨텍스트에서 생성되어
// 브라우저가 키보드 포커스를 정상적으로 할당하지 않는 문제 발생
ensureLoggedIn().catch(error => {
  console.error('로그인 초기화 실패:', error);
});

// 게임 인스턴스는 동기적으로 즉시 생성 (키보드 입력 정상 동작 보장)
new Phaser.Game(config);

content.text:
`★ Insight ─────────────────────────────────────`
- `type: Phaser.AUTO`는 WebGL이 안 되면 Canvas2D로 자동 폴백 → Canvas2D는 WebGL보다 **3~10배 느림**
- `antialias: true`는 저사양 GPU(Intel 내장)에서 렌더링 비용을 크게 올림
- 둘 중 하나라도 해당되면 PC 사양에 따라 체감 차이가 극명하게 남
`─────────────────────────────────────────────────`

두 가지를 확인해야 합니다.

**1. 렌더러 진단** — 저사양 PC에서 브라우저 콘솔(F12)에 무엇이 찍히는지 확인:
```typescript
// main.ts 에서 게임 생성 후 추가
const game = new Phaser.Game(config);
game.events.once('ready', () => {
  console.log('renderer:', game.renderer.type === Phaser.WEBGL ? 'WebGL' : 'Canvas2D');
});
```

**2. 바로 적용 가능한 개선** — `antialias: false`로 변경:

이 게임은 픽셀이 선명한 스프라이트 스타일이라 antialiasing이 오히려 불필요합니다. 변경할까요?

```diff
render: {
-   antialias: true,
+   antialias: false,
    roundPixels: true
}
```

그리고 저사양 PC에서 **Canvas2D로 폴백되고 있다면** 그게 주범입니다. 이 경우는 `type: Phaser.WEBGL`로 강제할 수 있지만, 해당 PC가 WebGL을 지원하는지 먼저 확인이 필요합니다.

일단 `antialias: false` 먼저 적용해드릴까요?

